'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/list/md-gb-list.js';
import '@material/web/labs/gb/components/list/md-gb-list-item.js';
import {ListElement} from '@material/web/labs/gb/components/list/list-element.js';
import {ListItemElement} from '@material/web/labs/gb/components/list/list-item-element.js';

/**
 * A Material Design component. Wraps <md-gb-list>.
 * Docs: https://material-web.dev/3.0/components/list/
 */
export const MdList = createComponent({
  react: React,
  tagName: 'md-gb-list',
  elementClass: ListElement,
  events: {
    onItemselectionchange: 'itemselectionchange' as EventName<Event>,
    onReorder: 'reorder' as EventName<Event>,
  },
});

export type MdListProps = React.ComponentProps<typeof MdList>;

/**
 * A Material Design component. Wraps <md-gb-list-item>.
 * Docs: https://material-web.dev/3.0/components/list/
 */
export const MdListItem = createComponent({
  react: React,
  tagName: 'md-gb-list-item',
  elementClass: ListItemElement,
  events: {
    onRevealChange: 'reveal-change' as EventName<Event>,
    onToggle: 'toggle' as EventName<Event>,
  },
});

export type MdListItemProps = React.ComponentProps<typeof MdListItem>;
